//<script>
(async () => {
  const TITLE = '以太网与 USB 网络共享守护';
  const BUTTON_TITLE = '网络共享守护';
  const MODAL_NAME = 'kano_tether_guard_modal';
  const STYLE_ID = 'kano_tether_guard_style';
  const STORAGE_DIR = '/data/kano_tether_guard';
  const HELPER_FILE = `${STORAGE_DIR}/ethernet-tether`;
  const SERVICE_FILE = `${STORAGE_DIR}/service.sh`;
  const VERSION_FILE = `${STORAGE_DIR}/deployment.version`;
  // build-plugin.ps1 replaces this with a fingerprint of this template and helper.
  const DEPLOYMENT_VERSION = 'auto-c62992251893-e67f3140e8a4';
  const DEPLOYMENT_VERSION_LABEL = `v${DEPLOYMENT_VERSION.replace(/^auto-/, '').split('-')[0].slice(0, 8)}`;
  const PID_FILE = `${STORAGE_DIR}/guard.pid`;
  const LOG_FILE = `${STORAGE_DIR}/guard.log`;
  const GUARD_CONFIG_FILE = `${STORAGE_DIR}/guard.conf`;
  const BOOT_SH_FILE = '/sdcard/ufi_tools_boot.sh';
  const BOOT_LINE = `${SERVICE_FILE} boot >/dev/null 2>&1 &`;
  const UNINSTALL_TOAST_ID = 'kano_tether_guard_uninstall_toast';
  const HELPER_BASE64 = '';
  const HELPER_SHA256 = 'e67f3140e8a4de7fe6aab4edb1bad12d2b7af78a8617c805a253836f1ec06613';

  const state = {
    usbEnabled: false,
    usbRaw: '',
    ethernetEnabled: false,
    ethernetRequests: 0,
    guardRunning: false,
    guardPid: '',
    guardUsb: true,
    guardEthernet: true,
    autoBoot: false,
    installed: false,
    deploymentUpdated: false,
    deploymentStatus: '尚未检查更新',
    log: '',
    busy: false,
  };

  const wait = (ms = 100) => new Promise((resolve) => setTimeout(resolve, ms));
  const shellQuote = (value = '') => `'${String(value).replace(/'/g, `'\\''`)}'`;
  const escapeHtml = (value = '') => String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  const run = async (command, timeout = 30000) => {
    // runShellWithRoot.success only confirms transport submission. Preserve the
    // actual shell exit code so a failed deployment cannot look successful.
    const exitMarker = '__KANO_TETHER_EXIT__:';
    const wrappedCommand = [
      '(',
      command,
      ')',
      '__kano_tether_rc=$?',
      `printf '${exitMarker}%s\\n' "$__kano_tether_rc"`,
    ].join('\n');
    const result = await runShellWithRoot(wrappedCommand, timeout);
    const output = String(result?.content || '').replace(/\r/g, '');
    const markerPattern = new RegExp(`(?:^|\\n)${exitMarker}(\\d+)\\s*$`);
    const match = output.match(markerPattern);
    const exitCode = match ? Number(match[1]) : null;
    return {
      ok: Boolean(result?.success) && (exitCode === null || exitCode === 0),
      text: output.replace(markerPattern, '').trim(),
      raw: result,
    };
  };

  const encodeText = (value) => {
    try {
      return btoa(unescape(encodeURIComponent(String(value || ''))));
    } catch {
      return '';
    }
  };

  const buildServiceScript = () => `#!/system/bin/sh
# kano auto generated: Ethernet and USB tethering guard

PATH=/system/bin:/system/xbin:/vendor/bin:$PATH
DIR=${STORAGE_DIR}
HELPER=${HELPER_FILE}
SCRIPT=${SERVICE_FILE}
PID_FILE=${PID_FILE}
LOCK_DIR="$DIR/start.lock"
LOG_FILE=${LOG_FILE}
CONFIG_FILE=${GUARD_CONFIG_FILE}
LOG_MAX_BYTES=524288
LOG_KEEP_BYTES=262144
EVENT_PID=""
LAST_ETH_ATTEMPT=0
LAST_USB_ATTEMPT=0
LAST_EVENT_CHECK=0
EVENT_DEBOUNCE_SECONDS=10
EVENT_TIMEOUT_SECONDS=300

# Missing configuration is treated as "guard both", preserving the behavior of
# earlier versions after an in-place upgrade.
GUARD_USB=1
GUARD_ETHERNET=1
if [ -r "$CONFIG_FILE" ]; then
  . "$CONFIG_FILE"
fi
case "$GUARD_USB" in 0|1) ;; *) GUARD_USB=1 ;; esac
case "$GUARD_ETHERNET" in 0|1) ;; *) GUARD_ETHERNET=1 ;; esac

rotate_log() {
  size="$(wc -c < "$LOG_FILE" 2>/dev/null)"
  case "$size" in *[!0-9]*|'') size=0 ;; esac
  if [ "$size" -ge "$LOG_MAX_BYTES" ]; then
    tail -c "$LOG_KEEP_BYTES" "$LOG_FILE" > "$LOG_FILE.tmp" 2>/dev/null && mv -f "$LOG_FILE.tmp" "$LOG_FILE"
  fi
}

log_line() {
  mkdir -p "$DIR"
  rotate_log
  printf '%s %s\n' "$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || echo '[no-date]')" "$*" >> "$LOG_FILE"
}

read_pid() {
  timeout 2s awk 'NR == 1 { print; exit }' "$PID_FILE" 2>/dev/null
}

is_guard_running() {
  pid="$(read_pid)"
  case "$pid" in *[!0-9]*|'') return 1 ;; esac
  [ -d "/proc/$pid" ] || return 1
  tr '\\000' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -Fq "$SCRIPT daemon"
}

usb_is_enabled() {
  usb_state="$(getprop sys.usb.state 2>/dev/null)"
  case ",$usb_state," in *,rndis,*) ;; *) return 1 ;; esac
  # RNDIS alone only means the USB gadget mode is selected.  An active
  # tether needs a USB/RNDIS network interface with an IPv4 address as well.
  for path in /sys/class/net/usb* /sys/class/net/rndis*; do
    [ -d "$path" ] || continue
    iface="\${path##*/}"
    ip -o -4 addr show dev "$iface" 2>/dev/null | awk '$3 == "inet" { found=1 } END { exit found ? 0 : 1 }' && return 0
  done
  return 1
}

now_seconds() {
  now="$(date +%s 2>/dev/null)"
  case "$now" in *[!0-9]*|'') now=0 ;; esac
  printf '%s\n' "$now"
}

ensure_ethernet() {
  "$HELPER" status >/dev/null 2>&1 && return 0
  now="$(now_seconds)"
  [ $((now - LAST_ETH_ATTEMPT)) -ge 5 ] || return 0
  LAST_ETH_ATTEMPT="$now"
  output="$("$HELPER" on 2>&1)"
  rc=$?
  log_line "[repair] ethernet rc=$rc output=\${output:-<empty>}"
  return $rc
}

ensure_usb() {
  usb_is_enabled && return 0
  now="$(now_seconds)"
  [ $((now - LAST_USB_ATTEMPT)) -ge 5 ] || return 0
  LAST_USB_ATTEMPT="$now"
  output="$("$HELPER" usb-on 2>&1)"
  rc=$?
  if [ "$rc" -ne 0 ]; then
    log_line "[repair] usb binder_rc=$rc output=\${output:-<empty>}"
    return $rc
  fi
  log_line "[repair] usb rc=0 output=\${output:-<empty>}"
  return 0
}

ensure_all() {
  [ "$GUARD_ETHERNET" = "1" ] && ensure_ethernet || true
  [ "$GUARD_USB" = "1" ] && ensure_usb || true
}

maybe_ensure_all() {
  now="$(now_seconds)"
  [ $((now - LAST_EVENT_CHECK)) -ge "$EVENT_DEBOUNCE_SECONDS" ] || return 0
  LAST_EVENT_CHECK="$now"
  ensure_all
}

cleanup_daemon() {
  [ -n "$EVENT_PID" ] && kill_tree "$EVENT_PID" || true
  owner="$(read_pid)"
  [ "$owner" = "$$" ] && rm -f "$PID_FILE"
}

kill_tree() {
  local target children child
  target="$1"
  case "$target" in *[!0-9]*|'') return 0 ;; esac
  children="$(timeout 2s awk 'NR == 1 { print; exit }' "/proc/$target/task/$target/children" 2>/dev/null)"
  for child in $children; do kill_tree "$child"; done
  kill "$target" >/dev/null 2>&1 || true
}

run_daemon() {
  mkdir -p "$DIR"
  trap 'cleanup_daemon; exit 0' INT TERM HUP
  trap 'cleanup_daemon' EXIT
  log_line "[daemon] started pid=$$ usb=$GUARD_USB ethernet=$GUARD_ETHERNET"
  while true; do
    ensure_all
    begin="$(now_seconds)"
    timeout "\${EVENT_TIMEOUT_SECONDS}s" logcat -b all -v brief -T 1 \
      'Tethering:I' 'TetheringService:I' 'EthernetTracker:I' 'UsbDeviceManager:I' '*:S' 2>/dev/null | \
      while IFS= read -r event_line; do
        maybe_ensure_all
      done
    finish="$(now_seconds)"
    elapsed=$((finish - begin))
    [ "$elapsed" -ge 5 ] || sleep 10
  done
}

start_guard() {
  mkdir -p "$DIR"
  if ! mkdir "$LOCK_DIR" >/dev/null 2>&1; then
    # Another start may be finishing; retain the original settling window for
    # this rare concurrent-start case.
    sleep 1
    is_guard_running && return 0
    rm -rf "$LOCK_DIR"
    mkdir "$LOCK_DIR" >/dev/null 2>&1 || return 1
  fi
  if is_guard_running; then
    rm -rf "$LOCK_DIR"
    return 0
  fi
  rm -f "$PID_FILE"
  sh "$SCRIPT" daemon >/dev/null 2>&1 &
  daemon_pid=$!
  printf '%s\n' "$daemon_pid" > "$PID_FILE"
  rm -rf "$LOCK_DIR"
  count=0
  # Return as soon as the daemon is observable, while keeping the original
  # one-second startup confirmation window for a busy device.
  while [ "$count" -lt 10 ]; do
    if is_guard_running; then
      log_line "[service] guard started pid=$daemon_pid"
      return 0
    fi
    sleep 0.1
    count=$((count + 1))
  done
  log_line "[service] guard failed to start pid=$daemon_pid"
  return 1
}

stop_guard() {
  if is_guard_running; then
    pid="$(read_pid)"
    kill_tree "$pid"
    count=0
    # Keep the original three-second graceful-stop window before force-killing
    # so a slow logcat child cannot overlap the next daemon instance.
    while kill -0 "$pid" >/dev/null 2>&1 && [ "$count" -lt 30 ]; do
      sleep 0.1
      count=$((count + 1))
    done
    kill -9 "$pid" >/dev/null 2>&1 || true
    log_line "[service] guard stopped pid=$pid"
  fi
  rm -f "$PID_FILE"
  rm -rf "$LOCK_DIR"
}

case "$1" in
  start) start_guard ;;
  stop) stop_guard ;;
  restart) stop_guard; start_guard ;;
  once) ensure_all ;;
  status)
    if is_guard_running; then
      echo "running pid=$(read_pid)"
      exit 0
    fi
    echo "stopped"
    exit 1
    ;;
  daemon) run_daemon ;;
  boot)
    sleep 12
    start_guard
    ;;
  *) echo "usage: $0 {start|stop|restart|once|status|boot}"; exit 2 ;;
esac
`;

  const ensureStyle = () => {
    if (document.getElementById(STYLE_ID)) return;
    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      #${MODAL_NAME} .tg-wrap { display:flex; flex-direction:column; gap:12px; }
      #${MODAL_NAME} .tg-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
      #${MODAL_NAME} .tg-card { padding:12px; border-radius:14px; border:1px solid rgba(255,255,255,.08); background:rgba(255,255,255,.04); }
      #${MODAL_NAME} .tg-status-panel { padding:7px; }
      #${MODAL_NAME} .tg-status-item { min-width:0; padding:9px 10px; border-radius:10px; background:rgba(255,255,255,.035); }
      #${MODAL_NAME} .tg-status-main { display:flex; align-items:center; justify-content:space-between; gap:8px; }
      #${MODAL_NAME} .tg-status-copy { min-width:0; }
      #${MODAL_NAME} .tg-status-line { display:flex; align-items:center; flex-wrap:wrap; gap:7px; }
      #${MODAL_NAME} .tg-status-item .tg-value { margin-top:0; }
      #${MODAL_NAME} .tg-status-item .tg-tip { margin-top:4px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
      #${MODAL_NAME} .tg-status-item button { flex:0 0 auto; padding:6px 10px; font-size:.62rem; }
      #${MODAL_NAME} .tg-label { font-size:.66rem; opacity:.76; }
      #${MODAL_NAME} .tg-value { margin-top:7px; font-size:.86rem; font-weight:800; word-break:break-word; }
      #${MODAL_NAME} .tg-chip { display:inline-flex; align-items:center; padding:4px 10px; border-radius:999px; font-size:.64rem; font-weight:800; }
      #${MODAL_NAME} .tg-chip[data-kind="good"] { color:#9dffbf; background:rgba(60,201,120,.16); }
      #${MODAL_NAME} .tg-chip[data-kind="warn"] { color:#ffd08a; background:rgba(255,173,51,.16); }
      #${MODAL_NAME} .tg-actions { display:flex; flex-wrap:wrap; gap:8px; }
      #${MODAL_NAME} .tg-targets { display:flex; flex-wrap:wrap; gap:10px; margin-top:10px; }
      #${MODAL_NAME} .tg-check { display:flex; align-items:center; gap:7px; padding:8px 10px; border-radius:10px; background:rgba(255,255,255,.035); font-size:.7rem; font-weight:700; }
      #${MODAL_NAME} .tg-check input { width:auto; margin:0; accent-color:#62d9ff; }
      #${MODAL_NAME} .tg-row { display:flex; align-items:center; justify-content:space-between; gap:12px; }
      #${MODAL_NAME} .tg-title { font-size:.8rem; font-weight:800; }
      #${MODAL_NAME} .tg-tip { margin-top:7px; font-size:.64rem; line-height:1.65; opacity:.76; }
      #${MODAL_NAME} pre { margin:8px 0 0; padding:10px 12px; max-height:220px; overflow:auto; white-space:pre-wrap; word-break:break-word; border-radius:12px; background:rgba(255,255,255,.03); font-size:.62rem; line-height:1.65; }
      #${MODAL_NAME} > .content { position:relative; }
      #${MODAL_NAME} .tg-loading { position:absolute; inset:0; z-index:20; display:flex; align-items:center; justify-content:center; flex-direction:column; gap:10px; background:var(--dark-card-bg); border-radius:inherit; }
      #${MODAL_NAME} .tg-loading[data-hidden="1"] { display:none; }
      #${MODAL_NAME} .tg-spinner { width:28px; height:28px; border:3px solid rgba(255,255,255,.18); border-top-color:#fff; border-radius:50%; animation:tg-spin .8s linear infinite; }
      @keyframes tg-spin { to { transform:rotate(360deg); } }
      @media(max-width:700px) { #${MODAL_NAME} .tg-grid { grid-template-columns:1fr; } #${MODAL_NAME} .tg-actions button { width:100%; } }
    `;
    document.head.appendChild(style);
  };

  const setBusy = (busy, text = '处理中...') => {
    state.busy = busy;
    const root = document.querySelector(`#${MODAL_NAME}`);
    if (!root) return;
    root.querySelectorAll('button,input').forEach((el) => { el.disabled = busy; });
    const loading = root.querySelector('#tg_loading');
    if (loading) {
      loading.dataset.hidden = busy ? '0' : '1';
      const label = loading.querySelector('.tg-loading-text');
      if (label) label.textContent = text;
    }
  };

  // Some UFI/Magisk root transports truncate a large command string.  Write
  // Base64 in small root calls so the 78 KiB helper always deploys intact.
  const writeBase64File = async (path, encoded, mode, expectedSha = '') => {
    if (!encoded) return false;
    const payloadPath = `${path}.payload`;
    const tempPath = `${path}.new`;
    const prepare = await run(`
mkdir -p ${shellQuote(STORAGE_DIR)}
rm -f ${shellQuote(payloadPath)} ${shellQuote(tempPath)}
: > ${shellQuote(payloadPath)}
`, 10000);
    if (!prepare.ok) return false;

    const chunks = String(encoded).match(/.{1,3072}/g) || [];
    for (const chunk of chunks) {
      const append = await run(`printf '%s' ${shellQuote(chunk)} >> ${shellQuote(payloadPath)}`, 10000);
      if (!append.ok) {
        await run(`rm -f ${shellQuote(payloadPath)}`, 10000);
        return false;
      }
    }

    const decode = await run(`
base64 -d ${shellQuote(payloadPath)} > ${shellQuote(tempPath)} || { rm -f ${shellQuote(tempPath)} ${shellQuote(payloadPath)}; exit 1; }
rm -f ${shellQuote(payloadPath)}
chmod ${mode} ${shellQuote(tempPath)}
`, 30000);
    if (!decode.ok) return false;
    if (expectedSha) {
      const verify = await run(`
actual="$(sha256sum ${shellQuote(tempPath)} 2>/dev/null | awk '{print $1}')"
[ "$actual" = ${shellQuote(expectedSha)} ]
`, 10000);
      if (!verify.ok) {
        await run(`rm -f ${shellQuote(tempPath)}`, 10000);
        return false;
      }
    }
    const commit = await run(`mv -f ${shellQuote(tempPath)} ${shellQuote(path)}`, 10000);
    return commit.ok;
  };

  const writeTextFile = async (path, content, mode) => writeBase64File(path, encodeText(content), mode);

  const ensureInstalled = async () => {
    state.deploymentUpdated = false;
    const currentResult = await run(`
installed_version="$(cat ${shellQuote(VERSION_FILE)} 2>/dev/null)"
actual="$(sha256sum ${shellQuote(HELPER_FILE)} 2>/dev/null | awk '{print $1}')"
[ "$installed_version" = ${shellQuote(DEPLOYMENT_VERSION)} ] &&
[ "$actual" = ${shellQuote(HELPER_SHA256)} ] &&
[ -x ${shellQuote(SERVICE_FILE)} ]
`, 10000);
    if (currentResult.ok) {
      state.deploymentStatus = '检查完成：已是最新';
      return true;
    }

    // Stop an old running script before replacing it.  The user's guard scope
    // and boot configuration remain in place; only packaged components change.
    const runningResult = await run(`[ -x ${shellQuote(SERVICE_FILE)} ] && ${shellQuote(SERVICE_FILE)} status`, 10000);
    const wasRunning = runningResult.ok;
    if (wasRunning) {
      const stopResult = await run(`${shellQuote(SERVICE_FILE)} stop`, 30000);
      if (!stopResult.ok) {
        state.deploymentStatus = '更新失败：无法停止旧守护';
        return false;
      }
    }

    const helperState = await run(`
actual="$(sha256sum ${shellQuote(HELPER_FILE)} 2>/dev/null | awk '{print $1}')"
[ "$actual" = ${shellQuote(HELPER_SHA256)} ]
`, 10000);
    if (!helperState.ok && !(await writeBase64File(HELPER_FILE, HELPER_BASE64, '755', HELPER_SHA256))) {
      state.deploymentStatus = '更新失败：helper 部署失败';
      return false;
    }
    if (!(await writeTextFile(SERVICE_FILE, buildServiceScript(), '755'))) {
      state.deploymentStatus = '更新失败：守护脚本部署失败';
      return false;
    }
    if (!(await writeTextFile(VERSION_FILE, `${DEPLOYMENT_VERSION}\n`, '600'))) {
      state.deploymentStatus = '更新失败：版本标记写入失败';
      return false;
    }

    if (wasRunning) {
      const startResult = await run(`${shellQuote(SERVICE_FILE)} start`, 30000);
      if (!startResult.ok) {
        await run(`rm -f ${shellQuote(VERSION_FILE)}`, 10000);
        state.deploymentStatus = '更新失败：新守护启动失败';
        return false;
      }
    }
    state.deploymentUpdated = true;
    state.deploymentStatus = wasRunning ? '更新完成：守护已重启' : '更新完成：守护原本未运行';
    return true;
  };

  const writeGuardConfig = async (usb, ethernet) => {
    if (!usb && !ethernet) throw new Error('请至少选择 USB 或以太网中的一项守护');
    const content = `# 网络共享守护范围\nGUARD_USB=${usb ? 1 : 0}\nGUARD_ETHERNET=${ethernet ? 1 : 0}\n`;
    if (!(await writeTextFile(GUARD_CONFIG_FILE, content, '600'))) {
      throw new Error('守护范围保存失败');
    }
  };

  const collectStatus = async () => {
    const result = await run(`
usb_state="$(getprop sys.usb.state 2>/dev/null)"
usb_enabled=0
usb_iface=""
case ",$usb_state," in
  *,rndis,*)
    for path in /sys/class/net/usb* /sys/class/net/rndis*; do
      [ -d "$path" ] || continue
      iface="\${path##*/}"
      if ip -o -4 addr show dev "$iface" 2>/dev/null | awk '$3 == "inet" { found=1 } END { exit found ? 0 : 1 }'; then
        usb_enabled=1
        usb_iface="$iface"
        break
      fi
    done
    ;;
esac
eth_requests="$(dumpsys ethernet 2>/dev/null | awk -F: '/Tethered interface requests:/ { gsub(/[[:space:]]/, "", $2); print $2; exit }')"
case "$eth_requests" in *[!0-9]*|'') eth_requests=0 ;; esac
guard_usb="$(awk -F= '$1 == "GUARD_USB" { print $2; exit }' ${shellQuote(GUARD_CONFIG_FILE)} 2>/dev/null)"
guard_ethernet="$(awk -F= '$1 == "GUARD_ETHERNET" { print $2; exit }' ${shellQuote(GUARD_CONFIG_FILE)} 2>/dev/null)"
case "$guard_usb" in 0|1) ;; *) guard_usb=1 ;; esac
case "$guard_ethernet" in 0|1) ;; *) guard_ethernet=1 ;; esac
if [ -x ${shellQuote(SERVICE_FILE)} ] && ${shellQuote(SERVICE_FILE)} status >/dev/null 2>&1; then
  guard_running=1
  guard_pid="$(timeout 2s awk 'NR == 1 { print; exit }' ${shellQuote(PID_FILE)} 2>/dev/null)"
else
  guard_running=0
  guard_pid=""
fi
if [ -x ${shellQuote(HELPER_FILE)} ] && [ -x ${shellQuote(SERVICE_FILE)} ]; then installed=1; else installed=0; fi
touch ${shellQuote(BOOT_SH_FILE)}
if grep -qxF ${shellQuote(BOOT_LINE)} ${shellQuote(BOOT_SH_FILE)}; then auto_boot=1; else auto_boot=0; fi
echo "usb_enabled=$usb_enabled"
echo "usb_state=$usb_state"
echo "usb_iface=$usb_iface"
echo "eth_requests=$eth_requests"
echo "guard_running=$guard_running"
echo "guard_pid=$guard_pid"
echo "installed=$installed"
echo "auto_boot=$auto_boot"
echo "guard_usb=$guard_usb"
echo "guard_ethernet=$guard_ethernet"
`, 30000);
    if (!result.ok) throw new Error(result.text || '读取状态失败');
    const values = {};
    result.text.split('\n').forEach((line) => {
      const index = line.indexOf('=');
      if (index > 0) values[line.slice(0, index)] = line.slice(index + 1);
    });
    state.usbEnabled = values.usb_enabled === '1';
    state.usbRaw = [values.usb_state, values.usb_iface].filter(Boolean).join('；');
    state.ethernetRequests = Number.parseInt(values.eth_requests || '0', 10) || 0;
    state.ethernetEnabled = state.ethernetRequests > 0;
    state.guardRunning = values.guard_running === '1';
    state.guardPid = values.guard_pid || '';
    state.installed = values.installed === '1';
    state.autoBoot = values.auto_boot === '1';
    state.guardUsb = values.guard_usb !== '0';
    state.guardEthernet = values.guard_ethernet !== '0';
    const logResult = await run(`timeout 2s awk '{ lines[NR % 80] = $0 } END { start = NR > 80 ? NR - 79 : 1; for (i = start; i <= NR; i++) print lines[i % 80] }' ${shellQuote(LOG_FILE)} 2>/dev/null || true`, 10000);
    state.log = logResult.text;
  };

  const chip = (enabled, yes, no) => `<span class="tg-chip" data-kind="${enabled ? 'good' : 'warn'}">${enabled ? yes : no}</span>`;

  const render = () => {
    const root = document.querySelector(`#${MODAL_NAME}`);
    if (!root) return;
    root.querySelector('#tg_usb').innerHTML = chip(state.usbEnabled, '已开启', '已关闭');
    root.querySelector('#tg_usb_detail').textContent = state.usbRaw || '--';
    root.querySelector('#tg_eth').innerHTML = chip(state.ethernetEnabled, '已开启', '已关闭');
    root.querySelector('#tg_eth_detail').textContent = `请求数：${state.ethernetRequests}`;
    root.querySelector('#tg_guard').innerHTML = chip(state.guardRunning, '守护运行中', '守护未运行');
    const guardTargets = [state.guardUsb ? 'USB' : '', state.guardEthernet ? '以太网' : ''].filter(Boolean).join(' + ');
    root.querySelector('#tg_guard_detail').textContent = state.guardRunning ? `PID：${state.guardPid || '--'}；守护：${guardTargets}` : `已选择：${guardTargets}`;
    root.querySelector('#tg_boot').innerHTML = chip(state.autoBoot, '已启用', '未启用');
    const deploymentEl = root.querySelector('#tg_install');
    const shortStatus = state.deploymentStatus.replace(/^检查完成：/, '').replace(/^更新完成：/, '');
    deploymentEl.textContent = state.installed
      ? `${DEPLOYMENT_VERSION_LABEL} · ${shortStatus}`
      : `未部署 · ${shortStatus}`;
    deploymentEl.title = `部署版本：${DEPLOYMENT_VERSION}；${state.deploymentStatus}；守护范围：${guardTargets}`;
    root.querySelector('#tg_log').textContent = state.log || '暂无守护日志';
    root.querySelector('#tg_guard_toggle_btn').textContent = state.guardRunning ? '停止守护' : '启动守护';
    root.querySelector('#tg_boot_btn').textContent = state.autoBoot ? '关闭守护自启动' : '开启守护自启动';
    root.querySelector('#tg_guard_usb').checked = state.guardUsb;
    root.querySelector('#tg_guard_ethernet').checked = state.guardEthernet;
  };

  const refresh = async () => {
    await collectStatus();
    render();
  };

  const startGuard = async () => {
    setBusy(true, '正在部署并启动守护...');
    try {
      if (!(await ensureInstalled())) throw new Error('守护组件部署失败');
      const root = document.querySelector(`#${MODAL_NAME}`);
      await writeGuardConfig(root?.querySelector('#tg_guard_usb')?.checked, root?.querySelector('#tg_guard_ethernet')?.checked);
      const result = await run(`${shellQuote(SERVICE_FILE)} start`, 30000);
      if (!result.ok) throw new Error(result.text || '守护启动失败');
      await refresh();
      createToast('守护已启动，并已立即检查所选网络共享', 'green');
    } catch (error) {
      createToast(error?.message || '守护启动失败', 'red', 5000);
    } finally {
      setBusy(false);
    }
  };

  const stopGuard = async () => {
    setBusy(true, '正在停止守护...');
    try {
      const result = await run(`[ ! -x ${shellQuote(SERVICE_FILE)} ] || ${shellQuote(SERVICE_FILE)} stop`, 30000);
      if (!result.ok) throw new Error(result.text || '守护停止失败');
      await refresh();
      createToast('守护已停止；现有 USB/以太网共享保持不变', 'pink', 4500);
    } catch (error) {
      createToast(error?.message || '守护停止失败', 'red', 5000);
    } finally {
      setBusy(false);
    }
  };

  const applyGuardTargets = async () => {
    const root = document.querySelector(`#${MODAL_NAME}`);
    const usb = Boolean(root?.querySelector('#tg_guard_usb')?.checked);
    const ethernet = Boolean(root?.querySelector('#tg_guard_ethernet')?.checked);
    setBusy(true, '正在保存守护范围...');
    try {
      if (!(await ensureInstalled())) throw new Error('守护组件部署失败');
      await writeGuardConfig(usb, ethernet);
      if (state.guardRunning) {
        const result = await run(`${shellQuote(SERVICE_FILE)} restart`, 30000);
        if (!result.ok) throw new Error(result.text || '守护重启失败');
      }
      await refresh();
      createToast(state.guardRunning ? '守护范围已更新并生效' : '守护范围已保存；下次启动或开机自启时生效', 'green', 4500);
    } catch (error) {
      await refresh().catch(() => {});
      createToast(error?.message || '守护范围更新失败', 'red', 5000);
    } finally {
      setBusy(false);
    }
  };

  const enableTethering = async (kind) => {
    const isUsb = kind === 'usb';
    const label = isUsb ? 'USB 网络共享' : '以太网共享';
    setBusy(true, `正在开启${label}...`);
    try {
      if (!(await ensureInstalled())) throw new Error('共享组件部署失败');
      const command = isUsb
        ? `${shellQuote(HELPER_FILE)} usb-on`
        : `${shellQuote(HELPER_FILE)} on`;
      const result = await run(command, 30000);
      if (!result.ok) throw new Error(result.text || `${label}开启失败`);
      await refresh();
      createToast(`${label}已执行开启`, 'green');
    } catch (error) {
      createToast(error?.message || `${label}开启失败`, 'red', 6000);
    } finally {
      setBusy(false);
    }
  };

  const disableTethering = async (kind) => {
    const isUsb = kind === 'usb';
    const label = isUsb ? 'USB 网络共享' : '以太网共享';
    setBusy(true, `正在关闭${label}...`);
    try {
      if (!(await ensureInstalled())) throw new Error('共享组件部署失败');
      const command = isUsb
        ? `${shellQuote(HELPER_FILE)} usb-off`
        : `${shellQuote(HELPER_FILE)} ethernet-off`;
      const result = await run(command, 30000);
      if (!result.ok) throw new Error(result.text || `${label}关闭失败`);
      await refresh();
      const guardEnabled = isUsb ? state.guardUsb : state.guardEthernet;
      createToast(
        state.guardRunning && guardEnabled
          ? `${label}已关闭；守护仍会按配置重新开启`
          : `${label}已关闭`,
        'green',
        5000,
      );
    } catch (error) {
      createToast(error?.message || `${label}关闭失败`, 'red', 6000);
    } finally {
      setBusy(false);
    }
  };

  const confirmUninstall = () => new Promise((resolve) => {
    const old = document.getElementById(UNINSTALL_TOAST_ID);
    if (old) old.remove();
    const toast = createFixedToast(
      UNINSTALL_TOAST_ID,
      `<div style="pointer-events:all;width:86vw;max-width:420px">
        <div class="title" style="margin:0">确认卸载</div>
        <div style="margin-top:10px;font-size:.7rem;line-height:1.7">确定卸载网络共享守护吗？这会停止守护并删除其自启动配置和部署文件，但不会关闭当前 USB 或以太网共享。</div>
        <div style="margin-top:12px;display:flex;justify-content:flex-end;gap:10px">
          <button type="button" class="tg-uninstall-yes" disabled>是（3s）</button>
          <button type="button" class="tg-uninstall-no">否</button>
        </div>
      </div>`,
      { pointerEvents: 'all', zIndex: '100000' },
    );
    const root = toast?.el || document.getElementById(UNINSTALL_TOAST_ID);
    if (!root) {
      resolve(false);
      return;
    }
    const yesButton = root.querySelector('.tg-uninstall-yes');
    const noButton = root.querySelector('.tg-uninstall-no');
    let seconds = 3;
    let settled = false;
    const finish = (answer) => {
      if (settled) return;
      settled = true;
      clearInterval(timer);
      toast?.close ? toast.close() : root.remove();
      resolve(answer);
    };
    const timer = setInterval(() => {
      seconds -= 1;
      if (seconds > 0) {
        yesButton.textContent = `是（${seconds}s）`;
        return;
      }
      clearInterval(timer);
      yesButton.disabled = false;
      yesButton.textContent = '是，确认卸载';
    }, 1000);
    yesButton.onclick = () => {
      if (!yesButton.disabled) finish(true);
    };
    noButton.onclick = () => finish(false);
  });

  const uninstallGuard = async () => {
    if (!(await confirmUninstall())) return;
    setBusy(true, '正在卸载守护...');
    try {
      const bootPattern = BOOT_LINE.replace(/[\\.*^$[\]]/g, '\\$&');
      const result = await run(`
[ ! -x ${shellQuote(SERVICE_FILE)} ] || ${shellQuote(SERVICE_FILE)} stop
touch ${shellQuote(BOOT_SH_FILE)}
sed -i '\\#^${bootPattern}$#d' ${shellQuote(BOOT_SH_FILE)}
rm -rf ${shellQuote(STORAGE_DIR)}
`, 30000);
      if (!result.ok) throw new Error(result.text || '卸载失败');
      await refresh();
      createToast('守护已卸载；当前网络共享保持不变', 'green', 5000);
    } catch (error) {
      createToast(error?.message || '卸载失败', 'red', 6000);
    } finally {
      setBusy(false);
    }
  };

  const toggleAutoBoot = async () => {
    const wasAutoBoot = state.autoBoot;
    setBusy(true, wasAutoBoot ? '正在关闭自启动...' : '正在开启自启动...');
    try {
      if (!(await ensureInstalled())) throw new Error('守护组件部署失败');
      if (!wasAutoBoot) {
        const root = document.querySelector(`#${MODAL_NAME}`);
        await writeGuardConfig(root?.querySelector('#tg_guard_usb')?.checked, root?.querySelector('#tg_guard_ethernet')?.checked);
        if (state.guardRunning) {
          const restart = await run(`${shellQuote(SERVICE_FILE)} restart`, 30000);
          if (!restart.ok) throw new Error(restart.text || '守护重启失败');
        }
      }
      const result = wasAutoBoot
        ? await run(`touch ${shellQuote(BOOT_SH_FILE)}; sed -i '\\#^${BOOT_LINE.replace(/[\\.*^$[\]]/g, '\\$&')}$#d' ${shellQuote(BOOT_SH_FILE)}`, 30000)
        : await run(`touch ${shellQuote(BOOT_SH_FILE)}; grep -qxF ${shellQuote(BOOT_LINE)} ${shellQuote(BOOT_SH_FILE)} || echo ${shellQuote(BOOT_LINE)} >> ${shellQuote(BOOT_SH_FILE)}`, 30000);
      if (!result.ok) throw new Error('自启动配置更新失败');
      await refresh();
      createToast(wasAutoBoot ? '守护自启动已关闭' : '守护自启动已开启', 'green');
    } catch (error) {
      createToast(error?.message || '操作失败', 'red', 5000);
    } finally {
      setBusy(false);
    }
  };

  const openModal = async () => {
    ensureStyle();
    document.querySelector(`#${MODAL_NAME}`)?.remove();
    const { id, el } = createModal({
      name: MODAL_NAME,
      title: TITLE,
      maxWidth: '760px',
      showConfirm: false,
      contentStyle: 'max-height:72vh;',
      onClose: () => true,
      content: `
        <div class="tg-wrap">
          <div class="tg-card tg-status-panel">
            <div class="tg-grid">
              <div class="tg-status-item"><div class="tg-status-main"><div class="tg-status-copy"><div class="tg-status-line"><span class="tg-label">USB 共享</span><span class="tg-value" id="tg_usb"></span></div><div class="tg-tip" id="tg_usb_detail"></div></div><div class="tg-actions"><button type="button" id="tg_usb_on_btn">开启</button><button type="button" id="tg_usb_off_btn">关闭</button></div></div></div>
              <div class="tg-status-item"><div class="tg-status-main"><div class="tg-status-copy"><div class="tg-status-line"><span class="tg-label">以太网共享</span><span class="tg-value" id="tg_eth"></span></div><div class="tg-tip" id="tg_eth_detail"></div></div><div class="tg-actions"><button type="button" id="tg_eth_on_btn">开启</button><button type="button" id="tg_eth_off_btn">关闭</button></div></div></div>
              <div class="tg-status-item"><div class="tg-status-copy"><div class="tg-status-line"><span class="tg-label">守护</span><span class="tg-value" id="tg_guard"></span></div><div class="tg-tip" id="tg_guard_detail"></div></div></div>
              <div class="tg-status-item"><div class="tg-status-copy"><div class="tg-status-line"><span class="tg-label">开机自启动</span><span class="tg-value" id="tg_boot"></span></div><div class="tg-tip" id="tg_install"></div></div></div>
            </div>
          </div>
          <div class="tg-card">
            <div class="tg-title">守护范围</div>
            <div class="tg-targets">
              <label class="tg-check"><input type="checkbox" id="tg_guard_usb" checked> USB 网络共享</label>
              <label class="tg-check"><input type="checkbox" id="tg_guard_ethernet" checked> 以太网共享</label>
              <button type="button" id="tg_apply_targets_btn">应用守护范围</button>
            </div>
            <div class="tg-tip">可单选 USB、单选以太网，或同时选择两项。此范围也会用于开机自启动。</div>
          </div>
          <div class="tg-card">
            <div class="tg-title">操作</div>
            <div class="tg-actions" style="margin-top:10px">
              <button type="button" id="tg_guard_toggle_btn">启动守护</button>
              <button id="tg_boot_btn">切换守护自启动</button>
              <button id="tg_refresh_btn">刷新状态</button>
              <button type="button" id="tg_uninstall_btn">卸载守护</button>
            </div>
            <div class="tg-tip">守护只负责在共享被关闭后重新拉起。停止守护不会关闭当前 USB 或以太网共享；开机自启将按上方范围启动。</div>
          </div>
          <details class="tg-card"><summary class="tg-title">最近守护日志</summary><pre id="tg_log"></pre></details>
        </div>
        <div class="tg-loading" id="tg_loading"><div class="tg-spinner"></div><div class="tg-loading-text">正在加载...</div></div>
      `,
    });
    el.style.width = '94%';
    showModal(id);
    el.querySelector('#tg_usb_on_btn').onclick = async () => enableTethering('usb');
    el.querySelector('#tg_usb_off_btn').onclick = async () => disableTethering('usb');
    el.querySelector('#tg_eth_on_btn').onclick = async () => enableTethering('ethernet');
    el.querySelector('#tg_eth_off_btn').onclick = async () => disableTethering('ethernet');
    el.querySelector('#tg_guard_toggle_btn').onclick = async () => {
      if (state.guardRunning) await stopGuard(); else await startGuard();
    };
    el.querySelector('#tg_apply_targets_btn').onclick = applyGuardTargets;
    el.querySelector('#tg_boot_btn').onclick = toggleAutoBoot;
    el.querySelector('#tg_uninstall_btn').onclick = uninstallGuard;
    el.querySelector('#tg_refresh_btn').onclick = async () => {
      setBusy(true, '正在刷新状态...');
      try {
        await refresh();
        createToast('状态已刷新', 'pink');
      } catch (error) {
        createToast(error?.message || '状态读取失败', 'red');
      } finally {
        setBusy(false);
      }
    };
    setBusy(true, '正在检查守护更新...');
    try {
      if (!(await ensureInstalled())) throw new Error('守护组件更新失败');
      await refresh();
      if (state.deploymentUpdated) {
        createToast('已更新守护组件，并重启原本运行中的守护', 'green', 4500);
      }
    } catch (error) {
      createToast(error?.message || '守护检查失败', 'red', 5000);
    } finally {
      setBusy(false);
    }
  };

  const mainButton = document.createElement('button');
  mainButton.type = 'button';
  mainButton.textContent = BUTTON_TITLE;
  mainButton.onclick = async (event) => {
    event?.preventDefault();
    event?.stopPropagation();
    try {
      await openModal();
    } catch (error) {
      console.error('[以太网与 USB 网络共享守护] 打开模态框失败', error);
      createToast(`打开插件失败：${error?.message || '未知错误'}`, 'red', 6000);
    }
  };

  while (!document.querySelector('.actions-buttons')) await wait(120);
  document.querySelector('.actions-buttons')?.appendChild(mainButton);
})();
//</script>
